(function(){document.addEventListener("DOMContentLoaded",()=>{const body=document.body;const timeoutSeconds=parseInt(body.dataset.timeout,10);const logoutUrl=body.dataset.logoutUrl;if(!timeoutSeconds||!logoutUrl){console.error("Auto-logout: missing data-timeout or data-logout-url on <body>");return}const timeoutMs=timeoutSeconds*1000;let timer;function resetTimer(){clearTimeout(timer);timer=setTimeout(()=>{window.location.href=logoutUrl},timeoutMs)}["click","mousemove","keydown","scroll","touchstart"].forEach(evt=>{document.addEventListener(evt,resetTimer,true)});resetTimer()})})();
